INSERT INTO vehicle_catalog
    (id, make, model, generation, years, powertrain, fuel_kinds,
     tank_capacity_l, battery_capacity_kwh, pack_version)
SELECT seed.*, next_version.v FROM seed, next_version
ON CONFLICT (id) DO UPDATE SET
    make                 = EXCLUDED.make,
    model                = EXCLUDED.model,
    generation           = EXCLUDED.generation,
    years                = EXCLUDED.years,
    powertrain           = EXCLUDED.powertrain,
    fuel_kinds           = EXCLUDED.fuel_kinds,
    tank_capacity_l      = EXCLUDED.tank_capacity_l,
    battery_capacity_kwh = EXCLUDED.battery_capacity_kwh,
    pack_version         = EXCLUDED.pack_version;

-- Publish the version these rows were written at, exactly as CatalogPublishService
-- does: the state row IS the current pack version (migration 011).
UPDATE catalog_pack_state SET pack_version = GREATEST(pack_version, 2) + 1 WHERE singleton = 1;
